import numpy as np, math, json

def meshdata(name):
 ob=bpy.data.objects[name]; ev=ob.evaluated_get(bpy.context.evaluated_depsgraph_get()); m=ev.to_mesh(); m.calc_loop_triangles()
 v=np.array([list(ob.matrix_world@x.co) for x in m.vertices],dtype=float)
 tri=np.array([list(t.vertices) for t in m.loop_triangles],dtype=int)
 edges=sorted(set(tuple(sorted((int(t[i]),int(t[(i+1)%3])))) for t in tri for i in range(3)))
 return v,tri,edges

def pt(p,a,b,c):
 ab=b-a; ac=c-a; ap=p-a; d1=ab@ap; d2=ac@ap
 if d1<=0 and d2<=0:return a
 bp=p-b; d3=ab@bp; d4=ac@bp
 if d3>=0 and d4<=d3:return b
 vc=d1*d4-d3*d2
 if vc<=0 and d1>=0 and d3<=0:return a+(d1/(d1-d3))*ab
 cp=p-c; d5=ab@cp; d6=ac@cp
 if d6>=0 and d5<=d6:return c
 vb=d5*d2-d1*d6
 if vb<=0 and d2>=0 and d6<=0:return a+(d2/(d2-d6))*ac
 va=d3*d6-d5*d4
 if va<=0 and d4-d3>=0 and d5-d6>=0:return b+((d4-d3)/((d4-d3)+(d5-d6)))*(c-b)
 den=1/(va+vb+vc); return a+ab*(vb*den)+ac*(vc*den)

def ss(p1,q1,p2,q2):
 d1=q1-p1; d2=q2-p2; r=p1-p2; a=d1@d1; e=d2@d2; f=d2@r; c=d1@r; b=d1@d2; den=a*e-b*b
 s=np.clip((b*f-c*e)/den,0,1) if abs(den)>1e-24 else 0.
 t=(b*s+f)/e
 if t<0: t=0.;s=np.clip(-c/a,0,1)
 elif t>1:t=1.;s=np.clip((b-c)/a,0,1)
 return p1+d1*s,p2+d2*t

def hit(p,q,a,b,c):
 d=q-p; e1=b-a; e2=c-a; h=np.cross(d,e2); det=e1@h
 if abs(det)<1e-14:return None
 inv=1/det; s=p-a; u=inv*(s@h)
 if u< -1e-8 or u>1+1e-8:return None
 z=np.cross(s,e1); v=inv*(d@z)
 if v< -1e-8 or u+v>1+1e-8:return None
 t=inv*(e2@z)
 if t< -1e-8 or t>1+1e-8:return None
 return p+t*d

def wind(p,V,T):
 x=V[T]-p; a=x[:,0];b=x[:,1];c=x[:,2]; na=np.linalg.norm(a,axis=1);nb=np.linalg.norm(b,axis=1);nc=np.linalg.norm(c,axis=1)
 numer=np.einsum('ij,ij->i',a,np.cross(b,c));den=na*nb*nc+np.einsum('ij,ij->i',a,b)*nc+np.einsum('ij,ij->i',b,c)*na+np.einsum('ij,ij->i',c,a)*nb
 return float(np.sum(2*np.arctan2(numer,den))/(4*math.pi))
A,AT,AE=meshdata('Object_01')
result=[]
for name in ['Object_02','Object_03','Object_04']:
 B,BT,BE=meshdata(name); best=[float('inf'),None,None,None]
 def upd(x,y,kind):
  d=float(np.linalg.norm(x-y))
  if d<best[0]: best[:]=[d,x.tolist(),y.tolist(),kind]
 for p in A:
  for t in BT:upd(p,pt(p,*B[t]),'target_vertex/candidate_face')
 for p in B:
  for t in AT:upd(pt(p,*A[t]),p,'target_face/candidate_vertex')
 for i,j in AE:
  for k,l in BE:
   x,y=ss(A[i],A[j],B[k],B[l]);upd(x,y,'edge/edge')
 hits=[]
 for i,j in BE:
  for t in AT:
   h=hit(B[i],B[j],*A[t])
   if h is not None:hits.append(h.tolist())
 for i,j in AE:
  for t in BT:
   h=hit(A[i],A[j],*B[t])
   if h is not None:hits.append(h.tolist())
 bw=[wind(p,A,AT) for p in B]
 aw=[wind(p,B,BT) for p in A]
 inv=bpy.data.objects['Object_01'].matrix_world.inverted()
 local=[list(inv@__import__('mathutils').Vector(p.tolist())) for p in B]
 result.append({'name':name,'distance':best,'intersection_count':len(hits),'intersection_examples':hits[:5],'candidate_vertex_wind_in_target':bw,'target_vertices_inside_candidate':sum(abs(w)>0.5 for w in aw),'candidate_center_wind_in_target':wind(B.mean(axis=0),A,AT),'candidate_in_target_local':local,'aabb_overlap':[float(min(A[:,i].max(),B[:,i].max())-max(A[:,i].min(),B[:,i].min())) for i in range(3)]})
print(json.dumps(result))
